from pathlib import Path
root=Path('.')
root.joinpath('js/storage.js').write_text("""const Store = (() => {\n  const prefix='breizhBalade:';\n  const currentUserId=()=>{try{return String(window.BreizhAuth?.currentAccount?.()?.email||'').trim().toLowerCase();}catch(_){return '';}};\n  const scopedKey=key=>currentUserId()?`${prefix}user:${encodeURIComponent(currentUserId())}:${key}`:null;\n  const readJSON=(k,f)=>{try{const raw=localStorage.getItem(k);return raw?JSON.parse(raw):f;}catch(_){return f;}};\n  const read=(key,fallback)=>{const target=scopedKey(key);if(!target)return fallback;try{const existing=localStorage.getItem(target);if(existing!=null)return readJSON(target,fallback);const legacyKey=prefix+key,legacy=localStorage.getItem(legacyKey);if(legacy!=null){localStorage.setItem(target,legacy);localStorage.removeItem(legacyKey);return JSON.parse(legacy);}}catch(_){}return fallback;};\n  const write=(key,value)=>{const target=scopedKey(key);if(!target)return false;try{localStorage.setItem(target,JSON.stringify(value));return true;}catch(_){return false;}};\n  const toggleInArray=(key,id)=>{const list=read(key,[]);const next=list.includes(id)?list.filter(x=>x!==id):[...list,id];write(key,next);return next.includes(id);};\n  return {read,write,all:()=>({favorites:read('favorites',[]),later:read('later',[]),visited:read('visited',[]),notes:read('notes',{})}),isFavorite:id=>read('favorites',[]).includes(id),isLater:id=>read('later',[]).includes(id),isVisited:id=>read('visited',[]).includes(id),toggleFavorite:id=>toggleInArray('favorites',id),toggleLater:id=>toggleInArray('later',id),toggleVisited:id=>toggleInArray('visited',id),getNote:id=>read('notes',{})[id]||'',setNote:(id,note)=>{const notes=read('notes',{});notes[id]=note;return write('notes',notes);}};\n})();\n""",encoding='utf-8')
p=root/'js/geolocation.js';s=p.read_text(encoding='utf-8').replace("const raw = sessionStorage.getItem(storageKey) || localStorage.getItem(storageKey);","const raw = sessionStorage.getItem(storageKey);").replace("      sessionStorage.setItem(storageKey, JSON.stringify(payload));\n      localStorage.setItem(storageKey, JSON.stringify(payload));","      sessionStorage.setItem(storageKey, JSON.stringify(payload));").replace("        sessionStorage.removeItem(storageKey);\n        localStorage.removeItem(storageKey);","        sessionStorage.removeItem(storageKey);");p.write_text(s,encoding='utf-8')
p=root/'js/tide-credit.js';s=p.read_text(encoding='utf-8').replace('V2.1.6.11 — Crédit api-maree.fr non répétitif.','V2.3.0 — Mention de sécurité marée non répétitive.').replace('Données de marée calculées via api-maree.fr, à partir de composantes harmoniques issues de l’atlas Ifremer / PREVIMER.','Estimation locale indicative : vérifie toujours les horaires officiels de marée et les consignes locales avant une sortie littorale.');p.write_text(s,encoding='utf-8')
p=root/'manifest.webmanifest';s=p.read_text(encoding='utf-8').replace('Application mobile de balades, lieux naturels, patrimoine et découvertes en Bretagne.','Breizh’ Balade V2.3.0 : 71 lieux, balades nature, patrimoine et découvertes en Bretagne.');p.write_text(s,encoding='utf-8')
root.joinpath('service-worker.js').write_text("""/* Breizh’ Balade V2.3.0 — service worker léger */\nconst CACHE_NAME='breizh-balade-v2.3.0-public';\nconst APP_SHELL=['./','./index.html','./manifest.webmanifest','./css/style.css','./css/map.css','./css/responsive.css','./js/app.js','./js/tide-credit.js','./js/storage.js','./js/auth-local.js','./js/geolocation.js','./js/map.js','./data/places.js','./assets/logo/breizh-balade-logo.svg','./assets/logo/breizh-pattern.svg','./assets/icons/icon-192.png','./assets/icons/icon-512.png','./assets/places/coast.svg'];\nself.addEventListener('install',e=>e.waitUntil(caches.open(CACHE_NAME).then(c=>c.addAll(APP_SHELL)).then(()=>self.skipWaiting())));\nself.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('breizh-balade-')&&k!==CACHE_NAME).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));\nself.addEventListener('fetch',e=>{const r=e.request;if(r.method!=='GET')return;const u=new URL(r.url);if(u.origin!==self.location.origin)return;if(r.mode==='navigate'||['document','script','style','manifest'].includes(r.destination)){e.respondWith(fetch(r).then(resp=>{if(resp.ok)caches.open(CACHE_NAME).then(c=>c.put(r,resp.clone()));return resp;}).catch(()=>caches.match(r).then(x=>x||caches.match('./index.html'))));return;}e.respondWith(caches.match(r).then(x=>x||fetch(r).then(resp=>{if(resp.ok)caches.open(CACHE_NAME).then(c=>c.put(r,resp.clone()));return resp;}).catch(()=>r.destination==='image'?caches.match('./assets/places/coast.svg'):undefined)));});\n""",encoding='utf-8')
root.joinpath('CHANGEMENTS_V2.3.0_PUBLIC.md').write_text("""# Breizh’ Balade V2.3.0 — Publication publique\n\n- Explorer, Carte et Infos accessibles sans compte.\n- Compte local optionnel pour favoris, listes, notes et profil.\n- Données personnelles séparées par compte local.\n- Messages d’inscription/profil visibles.\n- Mot de passe local minimum 8 caractères.\n- Google/Facebook clairement désactivés tant qu’un backend réel n’est pas connecté.\n- Images en lazy loading, sans préchargement des 71 visuels.\n- Service worker allégé.\n- Géolocalisation limitée à la session et demandée après action utilisateur.\n- Clé API marée retirée ; estimation locale indicative.\n- Open Graph, canonical, métadonnées sociales et iOS.\n- Zoom mobile réactivé.\n""",encoding='utf-8')
